'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var suite = require( './shared.js' );


// VARIABLES //

var dlantr = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( dlantr instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlantr, 'function', 'main export is a function' );
	t.strictEqual( dlantr.length, 9, 'main arity is 9' );
	t.strictEqual( typeof dlantr.ndarray, 'function', 'ndarray method exists' );
	t.strictEqual( dlantr.ndarray.length, 12, 'ndarray arity is 12' );
	t.end();
});

suite( dlantr, 'native', opts );
